-- Make withdrawal history transparent: requested amount and service fee are separate ledger entries.
create or replace function public.request_wallet_withdrawal_v2(p_amount_ngn bigint,p_transaction_fee_ngn bigint,p_bank_account_id uuid) returns public.withdrawals language plpgsql security definer set search_path=public as $$ declare r public.withdrawals; w public.wallets; b public.bank_accounts; fee bigint; total bigint; begin if auth.uid() is null then raise exception 'UNAUTHENTICATED'; end if; select * into b from public.bank_accounts where id=p_bank_account_id and user_id=auth.uid(); if b.id is null then raise exception 'BANK_ACCOUNT_NOT_FOUND'; end if; select * into w from public.wallets where user_id=auth.uid() for update; if p_amount_ngn<5000 then raise exception 'MINIMUM_WITHDRAWAL_IS_5000'; end if; fee:=round(p_amount_ngn*0.02); total:=p_amount_ngn+fee; if w.balance_ngn<total then raise exception 'INSUFFICIENT_CASH_BALANCE_FOR_FEE'; end if; update public.wallets set balance_ngn=balance_ngn-total,updated_at=now() where user_id=auth.uid(); insert into public.withdrawals(user_id,amount_ngn,transaction_fee_ngn,status,bank_name,account_name,account_number_last4) values(auth.uid(),p_amount_ngn,fee,'pending',b.bank_name,b.account_name,right(b.account_number,4)) returning * into r; insert into public.wallet_transactions(user_id,transaction_type,amount_ngn,reference,metadata) values(auth.uid(),'withdrawal_debit',-p_amount_ngn,r.id::text,jsonb_build_object('withdrawal_id',r.id,'requested_ngn',p_amount_ngn,'description','Withdrawal request','bank_account_id',b.id,'account_last4',right(b.account_number,4))); insert into public.wallet_transactions(user_id,transaction_type,amount_ngn,reference,metadata) values(auth.uid(),'fee',-fee,r.id::text||'-FEE',jsonb_build_object('withdrawal_id',r.id,'fee_ngn',fee,'fee_rate','2%','fee_type','withdrawal','description','Withdrawal service fee')); insert into public.platform_fees(fee_type,amount_ngn,gross_amount_ngn,net_amount_ngn,user_id,reference,metadata) values('withdrawal',fee,total,p_amount_ngn,auth.uid(),r.id::text,jsonb_build_object('rate','2%')); return r; end; $$; grant execute on function public.request_wallet_withdrawal_v2(bigint,bigint,uuid) to authenticated;
